"""Repository access: discovery, config, signatures, objects, trees, index."""
import os
import time

from . import git


class RepoError(Exception):
    pass


class Signature:
    __slots__ = ("name", "email", "timestamp", "tz_offset")

    def __init__(self, name, email, timestamp=None, tz_offset=None):
        self.name = name
        self.email = email
        if timestamp is None:
            timestamp = int(time.time())
        if tz_offset is None:
            if time.localtime(timestamp).tm_isdst and time.daylight:
                tz_offset = -time.altzone
            else:
                tz_offset = -time.timezone
        self.timestamp = timestamp
        self.tz_offset = tz_offset

    def tz_string(self):
        off = self.tz_offset
        sign = "+" if off >= 0 else "-"
        off = abs(off)
        return "%s%02d%02d" % (sign, off // 3600, (off % 3600) // 60)

    def env_string(self):
        """Format usable for GIT_AUTHOR_DATE: '<ts> <tz>'."""
        return "%d %s" % (self.timestamp, self.tz_string())

    def __str__(self):
        return "%s <%s> %d %s" % (self.name, self.email, self.timestamp, self.tz_string())


class Repo:
    def __init__(self, start_dir=None):
        rc, out, err = git.run_git(
            ["rev-parse", "--git-dir", "--absolute-git-dir", "--show-toplevel",
             "--show-prefix", "--is-bare-repository"],
            cwd=start_dir, check=False)
        if rc != 0:
            raise RepoError(err.decode("utf-8", "replace").strip())
        lines = out.decode("utf-8", "replace").split("\n")
        self.git_dir = lines[1].strip()
        toplevel = lines[2].strip()
        self.worktree = toplevel if toplevel else None
        self.prefix = lines[3].strip()
        self.is_bare = lines[4].strip() == "true"

    # -- config -----------------------------------------------------------
    def config_get(self, key):
        rc, out, _ = git.run_git(["config", "--get", key], check=False)
        if rc != 0:
            return None
        return out.decode("utf-8", "replace").rstrip("\n")

    def config_get_all(self, key):
        rc, out, _ = git.run_git(["config", "--get-all", key], check=False)
        if rc != 0:
            return []
        return [l for l in out.decode("utf-8", "replace").split("\n") if l]

    # -- signatures -------------------------------------------------------
    def _sig(self, name_env, email_env):
        name = os.environ.get(name_env) or self.config_get("user.name")
        email = (os.environ.get(email_env) or self.config_get("user.email")
                 or self.config_get("user.name"))
        if not name:
            name = email or ""
        if not email:
            email = ""
        return Signature(name, email)

    def author_signature(self):
        return self._sig("GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL")

    def committer_signature(self):
        return self._sig("GIT_COMMITTER_NAME", "GIT_COMMITTER_EMAIL")

    # -- refs ---------------------------------------------------------------
    def rev_parse(self, rev):
        rc, out, _ = git.run_git(["rev-parse", "--verify", "-q", rev], check=False)
        if rc != 0:
            return None
        return out.decode().strip()

    def current_branch(self):
        rc, out, _ = git.run_git(["symbolic-ref", "-q", "--short", "HEAD"], check=False)
        if rc != 0:
            return None
        return out.decode().strip()

    def update_ref(self, ref, oid, old=None):
        args = ["update-ref", ref, oid]
        if old is not None:
            args.append(old)
        git.run_git(args)

    def delete_ref(self, ref):
        git.run_git(["update-ref", "-d", ref], check=False)

    # -- objects ------------------------------------------------------------
    def hash_object(self, data):
        out = git.git_out(["hash-object", "-w", "--stdin"], input=data)
        return out.decode().strip()

    def cat_file(self, oid):
        return git.git_out(["cat-file", "-p", oid])

    def object_type(self, oid):
        rc, out, _ = git.run_git(["cat-file", "-t", oid], check=False)
        if rc != 0:
            return None
        return out.decode().strip()

    def parse_commit(self, oid):
        """Return dict with tree, parents, author, committer, message bytes."""
        out = git.git_out(["cat-file", "commit", oid])
        head, _, message = out.partition(b"\n\n")
        info = {"parents": [], "message": message}
        for line in head.split(b"\n"):
            if line.startswith(b"tree "):
                info["tree"] = line[5:].decode()
            elif line.startswith(b"parent "):
                info["parents"].append(line[7:].decode())
            elif line.startswith(b"author "):
                info["author"] = line[7:]
            elif line.startswith(b"committer "):
                info["committer"] = line[10:]
            elif line.startswith(b"encoding "):
                info["encoding"] = line[9:]
        return info

    def commit_tree(self, tree_oid, parents, author_raw, committer_sig, message_bytes,
                    extra_headers=None):
        """Create a commit. author_raw is the raw 'author' header bytes
        (e.g. 'Name <em> 123 +0000') or a Signature; committer_sig a Signature."""
        env = {}
        if isinstance(author_raw, Signature):
            env["GIT_AUTHOR_NAME"] = author_raw.name
            env["GIT_AUTHOR_EMAIL"] = author_raw.email
            env["GIT_AUTHOR_DATE"] = author_raw.env_string()
        else:
            name, email, date = split_ident(author_raw)
            env["GIT_AUTHOR_NAME"] = name
            env["GIT_AUTHOR_EMAIL"] = email
            env["GIT_AUTHOR_DATE"] = date
        env["GIT_COMMITTER_NAME"] = committer_sig.name
        env["GIT_COMMITTER_EMAIL"] = committer_sig.email
        env["GIT_COMMITTER_DATE"] = committer_sig.env_string()
        args = ["commit-tree", tree_oid]
        for p in parents:
            args += ["-p", p]
        out = git.git_out(args, env=env, input=message_bytes)
        return out.decode().strip()

    # -- trees ----------------------------------------------------------------
    def read_tree_entries(self, tree_oid):
        """Return dict path -> (mode, type, oid) for a tree, recursively."""
        out = git.git_out(["ls-tree", "-r", "-t", "-z", tree_oid])
        entries = {}
        if not out:
            return entries
        for rec in out.split(b"\x00"):
            if not rec:
                continue
            meta, _, path = rec.partition(b"\t")
            mode, typ, oid = meta.split(b" ")
            entries[path.decode("utf-8", "surrogateescape")] = (
                mode.decode(), typ.decode(), oid.decode())
        return entries

    def flatten_tree(self, tree_oid):
        """Return dict path -> (mode, oid) of blobs only (submodules as commits)."""
        entries = self.read_tree_entries(tree_oid)
        flat = {}
        for path, (mode, typ, oid) in entries.items():
            if typ in ("blob", "commit"):
                flat[path] = (mode, oid)
        return flat

    def write_tree_from_entries(self, entries):
        """Write a tree from dict path -> (mode, oid) using a temporary index.
        Returns the tree oid."""
        index_path = os.path.join(self.git_dir, "stg-index-%d" % os.getpid())
        env = {"GIT_INDEX_FILE": index_path}
        try:
            git.run_git(["read-tree", "--empty"], env=env)
            records = []
            for path in sorted(entries):
                mode, oid = entries[path]
                records.append("%s %s\t%s" % (mode, oid, path))
            data = ("\n".join(records) + "\n").encode("utf-8", "surrogateescape") if records else b""
            if records:
                # use --index-info with full blob spec lines
                lines = []
                for path in sorted(entries):
                    mode, oid = entries[path]
                    lines.append("%s blob %s\t%s" % (mode, oid, path))
                data = ("\n".join(lines) + "\n").encode("utf-8", "surrogateescape")
                git.run_git(["update-index", "--index-info"], env=env, input=data)
            out = git.git_out(["write-tree"], env=env)
            return out.decode().strip()
        finally:
            try:
                os.unlink(index_path)
            except OSError:
                pass

    def blob_content(self, oid):
        return git.git_out(["cat-file", "blob", oid])


def split_ident(raw):
    """Split raw ident bytes 'Name <email> ts tz' into (name, email, 'ts tz')."""
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", "surrogateescape")
    name, _, rest = raw.partition(" <")
    email, _, date = rest.partition("> ")
    return name, email, date

