"""StGit stack state: load/save refs/stacks/<branch> metadata."""
import json
import time

from . import git

STACK_VERSION = 5


class StackState:
    def __init__(self, branch, head, applied=None, unapplied=None, hidden=None,
                 patches=None, prev=None, commit=None):
        self.branch = branch
        self.prev = prev            # oid of previous state commit or None
        self.head = head            # oid of branch head commit
        self.applied = list(applied or [])
        self.unapplied = list(unapplied or [])
        self.hidden = list(hidden or [])
        self.patches = dict(patches or {})  # name -> oid
        self.commit = commit        # oid of the state commit this was loaded from

    def all_patches(self):
        return list(self.patches)

    def top(self):
        return self.applied[-1] if self.applied else None

    def patch_oid(self, name):
        return self.patches[name]

    def is_applied(self, name):
        return name in self.applied

    def serialize(self):
        data = {
            "version": STACK_VERSION,
            "prev": self.prev,
            "head": self.head,
            "applied": self.applied,
            "unapplied": self.unapplied,
            "hidden": self.hidden,
            "patches": {name: {"oid": oid} for name, oid in self.patches.items()},
        }
        return json.dumps(data, ensure_ascii=False, indent=2).encode("utf-8")

    def copy(self):
        return StackState(self.branch, self.head, self.applied, self.unapplied,
                          self.hidden, self.patches, self.prev, self.commit)


def stack_ref(branch):
    return "refs/stacks/%s" % branch


def patch_ref(branch, name):
    return "refs/patches/%s/%s" % (branch, name)


def is_initialized(repo, branch):
    return repo.rev_parse(stack_ref(branch)) is not None


def load_stack(repo, branch):
    """Load stack state for branch. Returns (StackState, initialized_flag)."""
    ref = stack_ref(branch)
    commit = repo.rev_parse(ref)
    if commit is None:
        head = repo.rev_parse("refs/heads/%s" % branch) or repo.rev_parse(branch)
        return StackState(branch, head), False
    try:
        data = git.git_out(["cat-file", "blob", "%s:stack.json" % ref])
    except git.GitError:
        head = repo.rev_parse("refs/heads/%s" % branch)
        return StackState(branch, head), False
    obj = json.loads(data.decode("utf-8"))
    patches = {}
    for name, meta in obj.get("patches", {}).items():
        patches[name] = meta["oid"]
    return StackState(
        branch,
        obj["head"],
        obj.get("applied", []),
        obj.get("unapplied", []),
        obj.get("hidden", []),
        patches,
        obj.get("prev"),
        commit,
    ), True


def patch_metadata_blob(repo, patch_oid):
    """Generate the content of patches/<name> blob for a patch commit."""
    info = repo.parse_commit(patch_oid)
    parent_tree = ""
    if info["parents"]:
        pinfo = repo.parse_commit(info["parents"][0])
        parent_tree = pinfo["tree"]
    name, email, date = _split_ident_parts(info.get("author", b""))
    ts, _, tz = date.partition(" ")
    try:
        ts_i = int(ts)
    except ValueError:
        ts_i = 0
    date_str = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(ts_i))
    tzoff = _tz_seconds(tz.strip())
    # Format date with the commit's own timezone
    date_str = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(ts_i + tzoff))
    date_str = "%s %s" % (date_str, tz.strip())
    head = ("Bottom: %s\nTop:    %s\nAuthor: %s <%s>\nDate:   %s\n"
            % (parent_tree, info["tree"], name, email, date_str))
    msg = info.get("message", b"")
    return head.encode("utf-8") + b"\n" + msg.rstrip(b"\n") + (b"\n" if msg.strip() else b"")


def _tz_seconds(tz):
    if not tz or len(tz) < 5:
        return 0
    sign = 1 if tz[0] == "+" else -1
    try:
        return sign * (int(tz[1:3]) * 3600 + int(tz[3:5]) * 60)
    except ValueError:
        return 0


def _split_ident_parts(raw):
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", "surrogateescape")
    name, _, rest = raw.partition(" <")
    email, _, date = rest.partition("> ")
    return name, email, date


def save_stack(repo, state, message, committer=None, author=None):
    """Write the stack state as two commits (simplified + full) and move the
    stack ref. Returns the new state commit oid."""
    if committer is None:
        committer = repo.committer_signature()
    if author is None:
        author = committer

    # Build tree: stack.json + patches/<name> for each patch
    entries = {}
    entries["stack.json"] = ("100644", repo.hash_object(state.serialize()))
    for name, oid in state.patches.items():
        blob = repo.hash_object(patch_metadata_blob(repo, oid))
        entries["patches/%s" % name] = ("100644", blob)
    tree = repo.write_tree_from_entries(entries)

    msg = message.encode("utf-8") if isinstance(message, str) else message

    # Simplified commit: parent is the simplified parent of the previous state
    prev_simplified = None
    if state.prev is not None:
        prev_full = repo.parse_commit(state.prev)
        if prev_full["parents"]:
            prev_simplified = prev_full["parents"][0]
    if prev_simplified is not None:
        simplified = repo.commit_tree(tree, [prev_simplified], author, committer, msg)
    else:
        simplified = repo.commit_tree(tree, [], author, committer, msg)

    # Full commit: parents = [simplified, head] + ([prev] if prev)
    parents = [simplified]
    if state.head is not None:
        parents.append(state.head)
    if state.prev is not None:
        parents.append(state.prev)
    full = repo.commit_tree(tree, parents, author, committer, msg)

    repo.update_ref(stack_ref(state.branch), full)
    return full
